SELECT r.* FROM openplat_api_system_relation r
LEFT JOIN openplat_api_config a ON r.api_id = a.id
WHERE a.api_path = #{apiPath} AND r.system_id = #{systemId}

SELECT * FROM openplat_api_system_relation


        AND api_id = #{apiId}


        AND system_id = #{systemId}


        AND status = #{status}
